update public.lessons l set enhancements = $ench${"industryStory":"On my first consulting engagement I watched a brilliant tester get ignored in planning because she described her approach in pure syllabus language — \"we'll apply decision table testing to the eligibility rules\". The room glazed over. A week later she said the same thing as \"let's list every combination of the three eligibility flags and test each row\". Identical technique, but now the developers leaned in and started spotting missing rows themselves. The concept was never the problem; the translation was.","visualAid":{"type":"comparison","title":"Syllabus term vs how teams actually say it","headers":["ISTQB term","What a team says on the floor"],"rows":[["Confirmation testing","\"Did the fix actually work?\""],["Regression testing","\"Did we break anything else?\""],["Equivalence partitioning","\"Which values are worth trying?\""],["Risk-based testing","\"What do we test first if time runs out?\""],["Test basis","\"What are we testing against — the ticket? the spec?\""]]},"davidTip":"David's Industry Perspective: In twenty years I have never once been asked in a stand-up to \"define equivalence partitioning\". I have been asked a hundred times \"which values did you try, and why those?\" — which is the same thing wearing work clothes. Learn the concept deeply enough that you can explain it without the label.","miniChallenge":"Take one ISTQB term you find dry — say \"test basis\" — and rewrite its meaning as a single plain question you could ask a developer.","modelAnswer":"## Example\n\"Test basis\" becomes: \"What are we actually checking this against — the acceptance criteria, the design doc, or someone's memory of the meeting?\" That question exposes weak requirements instantly, which is exactly what the concept is for.","resourcePreview":{"name":"Concept-to-Workplace Translation Card","purpose":"Maps the most-used syllabus terms to the plain language teams really use.","whenToUse":"Keep it beside you for your first month in a QA role.","formats":["PDF"]}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'istqb-foundation-masterclass'
  and m.module_number = 11 and l.lesson_number = 1;

update public.lessons l set enhancements = $ench${"industryStory":"A newly-qualified tester joined a team I was consulting for and, on day two, asked where the test plan document was. There wasn't one. He was genuinely alarmed — the syllabus had told him a test plan was mandatory. I sat with him and showed him where the \"plan\" actually lived: in the sprint board, the definition of done, the CI pipeline, and a shared risk conversation held every Monday. Within a month he'd stopped looking for the missing document and started contributing to the real, distributed one. The plan existed; it just didn't look like the exam's version.","visualAid":{"type":"comparison","title":"Syllabus process vs what companies actually do","headers":["ISTQB describes","What most teams actually do"],"rows":[["Separate test phase","Testing inside the sprint, continuously"],["Formal test plan document","Definition of done + risk conversation"],["Detailed test-case repository","Checklist in the ticket + exploratory notes"],["Test manager assigns work","Whole team owns quality"],["Signed test summary report","Dashboard + a message in the team channel"]]},"davidTip":"David's Industry Perspective: When I walk into a new client, I don't ask to see the test plan first — I ask what breaks in production and how they found out. The answer tells me more about their real testing maturity than any document ever could. Process artefacts are easy to fake; production outcomes are not.","miniChallenge":"Imagine you join a team with zero test documentation. Write down the three questions you'd ask to work out whether their testing is actually safe.","modelAnswer":"## Example\n1) \"What automated checks run on every commit, and what do they cover?\" 2) \"How do you decide what to test manually for a new story?\" 3) \"When something escapes to production, how do you find out and what happens next?\" The answers reveal whether the rigour simply moved out of documents and into practice.","badGood":{"label":"reading a team's maturity","bad":"\"This team has no formal test plan or test-case repository, so their testing must be immature and risky.\"","good":"\"This team has no formal test plan, but strong CI coverage, a clear definition of done, and a weekly risk review — the rigour lives in practice, not paperwork.\""}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'istqb-foundation-masterclass'
